-- 091_seed_exercise_details.sql
-- Tags and teaching content for public.exercise_details.
-- Generated from overhaul/out/exercise-details.json. Do not edit by hand.
-- Idempotent. Does not change public.exercises.

begin;

do $guard$
begin
  if to_regclass('public.exercise_details') is null then
    raise exception 'public.exercise_details does not exist. Apply 090_intake_and_exercise_details.sql first.';
  end if;
end
$guard$;

